import java.util.Arrays;

class Solution {
    public int minNumberOfSemesters(int n, int[][] relations, int k) {
            // prereq[i] holds the bitmask of all prerequisite courses for course i
                    int[] prereq = new int[n];
                            for (int[] rel : relations) {
                                        int prev = rel[0] - 1;
                                                    int next = rel[1] - 1;
                                                                prereq[next] |= (1 << prev);
                                                                        }

                                                                                int totalStates = 1 << n;
                                                                                        int[] dp = new int[totalStates];
                                                                                                Arrays.fill(dp, Integer.MAX_VALUE / 2);
                                                                                                        dp[0] = 0;

                                                                                                                for (int mask = 0; mask < totalStates; mask++) {
                                                                                                                            if (dp[mask] == Integer.MAX_VALUE / 2) {
                                                                                                                                            continue;
                                                                                                                                                        }

                                                                                                                                                                    // Find all courses available to take next
                                                                                                                                                                                int available = 0;
                                                                                                                                                                                            for (int i = 0; i < n; i++) {
                                                                                                                                                                                                            // If course i is not taken and all prerequisites are in mask
                                                                                                                                                                                                                            if ((mask & (1 << i)) == 0 && (prereq[i] & mask) == prereq[i]) {
                                                                                                                                                                                                                                                available |= (1 << i);
                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                        int availableCount = Integer.bitCount(available);

                                                                                                                                                                                                                                                                                                    // If available courses are <= k, take all of them
                                                                                                                                                                                                                                                                                                                if (availableCount <= k) {
                                                                                                                                                                                                                                                                                                                                int nextMask = mask | available;
                                                                                                                                                                                                                                                                                                                                                dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
                                                                                                                                                                                                                                                                                                                                                            } else {
                                                                                                                                                                                                                                                                                                                                                                            // Iterate through all submasks of 'available' that have exactly k courses
                                                                                                                                                                                                                                                                                                                                                                                            for (int submask = available; submask > 0; submask = (submask - 1) & available) {
                                                                                                                                                                                                                                                                                                                                                                                                                if (Integer.bitCount(submask) == k) {
                                                                                                                                                                                                                                                                                                                                                                                                                                        int nextMask = mask | submask;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                dp[nextMask] = Math.min(dp[nextMask], dp[mask] + 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return dp[totalStates - 1];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }